/*
 * abi_aligned_two_full_units_common.h
 * Two fields as wide as their type (unsigned :32, signed :32): 8-byte struct.
 *
 * Shared by abi_aligned_two_full_units_server.c (built with gcc) and abi_aligned_two_full_units_client.c (built with
 * the compiler under test).  The static helpers below are compiled separately by
 * each side, so every access to a bit-field is generated by that side's compiler.
 *
 * "A" and "B" are two distinct, fully populated value sets.
 */
#ifndef ABI_ALIGNED_TWO_FULL_UNITS_COMMON_H
#define ABI_ALIGNED_TWO_FULL_UNITS_COMMON_H


struct S {
    unsigned a : 32;
    signed int b : 32;
};

struct S_probe { char c; struct S m; };

static struct S zero_s;                       /* all-zero (static storage) */

static unsigned long alignof_S(void)
{
    return (unsigned long)&((struct S_probe *)0)->m;
}

static void set_A(struct S *p)
{
    p->a = 0xDEADBEEFu;
    p->b = -123456789;
}

static void set_B(struct S *p)
{
    p->a = 0x12345678u;
    p->b = 987654321;
}

static int check_A(const struct S *p)
{
    if (p->a != 0xDEADBEEFu) return 1;
    if (p->b != -123456789) return 2;
    return 0;
}

static int check_B(const struct S *p)
{
    if (p->a != 0x12345678u) return 1;
    if (p->b != 987654321) return 2;
    return 0;
}

static void set_first_B(struct S *p)
{
    p->a = 0x12345678u;
}

static int check_first_B_rest_A(const struct S *p)
{
    if (p->a != 0x12345678u) return 1;
    if (p->b != -123456789) return 2;
    return 0;
}

/* ---------------------------------------------------------------- server API */
unsigned long srv_sizeof_S(void);
unsigned long srv_alignof_S(void);
struct S srv_make_A(void);                    /* returns A */
struct S srv_make_B(void);                    /* returns B */
int  srv_check_A(struct S s);                 /* 0 if s == A, else field index */
int  srv_check_B(struct S s);
int  srv_check_A_ptr(const struct S *p);
void srv_set_B_ptr(struct S *p);              /* sets *p to B */
int  srv_check_array(const struct S *arr, int n);   /* even index = A, odd = B */
void srv_fill_array(struct S *arr, int n);          /* even index = A, odd = B */
int  srv_mixed_args(int a, struct S s, double d, struct S t, int b);
int  srv_many_args(int i1, int i2, int i3, int i4, struct S a, struct S b,
                   int i5, int i6, struct S c, int i7);
int  srv_call_client(struct S (*cb)(struct S, int));
int  srv_call_client_ptr(void (*cb)(struct S *));
extern struct S srv_global_A;                 /* statically initialised to A */
extern struct S srv_global_in;                /* written by the client */
int  srv_check_global_in(void);               /* expects A */
int  srv_check_global_first_B(void);          /* expects first field B, rest A */

#endif
